// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airDrop} from "../src/airDrop.sol";

contract InvMutTest is Test {
    airDrop c;
    function setUp() public { c = new airDrop(); }

    // Fuzz parameters: from, an array of receiver addresses, value v, decimals
    // We must ensure tos.length > 0 per the require in transfer.
    function testFuzz_property(address from, address to0, uint256 v, uint256 _decimals) public {
        // Ensure we have at least one recipient and it is a contract that can accept the call with selector
        vm.assume(to0 != address(0));
        vm.assume(from != address(0));
        // bound decimals to a reasonable range to avoid overflow in v * 10 ** _decimals
        _decimals = bound(_decimals, 0, 18);
        // bound v to avoid overflow when multiplied (keep wide)
        v = bound(v, 0, type(uint256).max / (10 ** _decimals == 0 ? 1 : 10 ** _decimals));

        // Deploy a recording helper that exposes the exact called function signature
        // so c.call(abi.encodeWithSelector(id, from, _tos[i], _value)) will succeed and we can observe it.
        Recorder r = new Recorder();

        // build recipients array with exactly one element to simplify observation
        address[] memory tos = new address[](1);
        tos[0] = address(r);

        // Call transfer and capture whether it returns (does not revert) and its return value.
        bool ok;
        bool ret;
        try c.transfer(from, address(r), tos, v, _decimals) returns (bool _ret) {
            ok = true;
            ret = _ret;
        } catch {
            ok = false;
            ret = false;
        }

        // The universal property: whenever transfer completes (ok==true) the reference contract returns true.
        // We assert that: for the reference implementation this always holds; the mutant that changed the
        // final `return true` to `return false` will make this assertion fail for some inputs that reach completion.
        if (ok) {
            assertTrue(ret, "Reference must return true when transfer completes");
        } else {
            // If it reverted, nothing to assert about return value; still ensure recorder saw nothing (optional)
            // No assertion here to avoid excluding valid revert behaviors.
        }

        // Additionally, validate that the recorder actually observed the call we expect when ok==true.
        // This is not the main assertion but helps ensure the call happened as part of the successful run.
        if (ok) {
            (address observedFrom, address observedTo, uint256 observedValue, uint256 calls) = r.read();
            // The recorder should have been invoked exactly once and recorded matching arguments
            assertTrue(calls == 1, "recorder saw exactly one call");
            assertTrue(observedFrom == from, "recorder observed from");
            assertTrue(observedTo == tos[0], "recorder observed to");
            assertTrue(observedValue == v * (10 ** _decimals), "recorder observed value");
        }
    }
}

// Recorder that exposes the exact signature transfer uses: transferFrom(address,address,uint256)
// and records the arguments and a call counter.
contract Recorder {
    address public lastFrom;
    address public lastTo;
    uint256 public lastValue;
    uint256 public calls;

    // The target selector is transferFrom(address,address,uint256)
    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        lastFrom = from;
        lastTo = to;
        lastValue = value;
        calls += 1;
        return true;
    }

    // helper to read all recorded data in one call
    function read() external view returns (address, address, uint256, uint256) {
        return (lastFrom, lastTo, lastValue, calls);
    }
}
